import assert from "node:assert/strict";
import test from "node:test";
import { analyzeLiquidation } from "../src/index.ts";

test("propone liquidazione per perizia e fattura allineate", () => {
  const result = analyzeLiquidation({
    practice: {
      claimId: "CLM-001",
      policyId: "POL-001",
      currency: "EUR",
      sourceRef: "claim://CLM-001",
    },
    appraisal: {
      appraisalId: "APP-001",
      claimId: "CLM-001",
      lines: [
        {
          itemCode: "BUMPER",
          description: "Paraurti anteriore",
          quantity: 1,
          total: { minorUnits: 100_00, currency: "EUR" },
          sourceRef: "appraisal://APP-001#line-1",
        },
      ],
      total: { minorUnits: 100_00, currency: "EUR" },
      sourceRef: "appraisal://APP-001",
    },
    invoice: {
      invoiceId: "INV-001",
      claimId: "CLM-001",
      lines: [
        {
          itemCode: "BUMPER",
          description: "Paraurti anteriore",
          quantity: 1,
          total: { minorUnits: 100_00, currency: "EUR" },
          sourceRef: "invoice://INV-001#line-1",
        },
      ],
      total: { minorUnits: 100_00, currency: "EUR" },
      sourceRef: "invoice://INV-001",
    },
    policy: {
      policyId: "POL-001",
      claimId: "CLM-001",
      covered: true,
      limit: { minorUnits: 500_00, currency: "EUR" },
      deductible: { minorUnits: 10_00, currency: "EUR" },
      sourceRef: "policy://POL-001",
    },
  });

  assert.equal(result.proposedDecision, "LIQUIDATE");
  assert.deepEqual(result.payableAmount, { minorUnits: 90_00, currency: "EUR" });
  assert.equal(result.amountStatus, "COMPUTED");
  assert.equal(result.requiresHumanReview, false);
  assert.equal(result.issues.length, 0);
});

