export { analyzeLiquidation } from "./liquidation.ts";
export {
  MOTIVATION_CATALOG,
  buildMotivationSystemPrompt,
  composeMotivation,
} from "./motivation.ts";

import type { LiquidationProposal, W2Input } from "./domain.ts";
import { analyzeLiquidation } from "./liquidation.ts";
import { composeMotivation } from "./motivation.ts";

export function evaluateLiquidation(input: W2Input, seed = input?.practice?.claimId || "UNKNOWN"): LiquidationProposal {
  const analysis = analyzeLiquidation(input);
  return {
    ...analysis,
    motivation: composeMotivation(analysis, seed),
  };
}
